// Cloudflare Worker entry: wraps the OpenNext-generated worker and adds a
// Cron Trigger so the collector is kicked even when nobody is visiting
// (GitHub's own schedule frequently skips runs).
// .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,
  async scheduled(_event, env, ctx) {
    // Runs the normal /api/cron route, which calls kickCollectorIfStale().
    const res = await handler.fetch(new Request("https://bb.appstac.com/api/cron"), env, ctx);
    console.log("cron kick:", res.status, await res.text());
  },
};

export * from "./.open-next/worker.js";
